const fs = require('fs');
const stage=(label,msg)=>console.log(`[v151-smoke] ${label} :: ${msg}`);
const watchdog=setTimeout(()=>{console.error('[v151-smoke] WATCHDOG_TIMEOUT :: gate exceeded 60s');process.exit(124)},60000);

async function deepest(page){let f=page.mainFrame(),chain=[];for(let i=0;i<18;i++){chain.push(f.url());const kids=f.childFrames();if(!kids.length)break;f=kids[0]}return {f,chain}}
